INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1700, 153, 1, 'النوع الرابع: الاستغفار', 0, '(ص294)', '', '', 'النوع الرابع الاستغفار', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1701, 153, 2, 'إنَّ اللهَ -جَلَّتْ حِكْمَتُه- ابتلى الإنسانَ بنفسه الأمَّارة بالسوء، وعدوِّه إبليس، والدنيا الفتانة، لكنه لم يُسْلِمْه لهؤلاء، بل أعانَه بِجُنْدٍ آخرينَ يؤزُّونه على الخير، وأمدَّه بمددٍ آخرَ يُقاوِم به هذا الابتلاء: فأرسل إليه رسولَه ﷺ، وأنزل عليه كتابَه، وأيَّده بمَلَكٍ كريم، هو واعظ الله في قلبه، يأمره بأمر ربه، ويبين له ما في طاعةِ عدوِّه من الهلاك.', 0, 'النوع الرابع: الاستغفار. (ص294)', '', '', 'إن الله -جلت حكمته- ابتلى الإنسان بنفسه الأمارة بالسوء وعدوه إبليس والدنيا الفتانة لكنه لم يسلمه لهؤلاء بل أعانه بجند آخرين يؤزونه على الخير وأمده بمدد آخر يقاوم به هذا الابتلاء فأرسل إليه رسوله وأنزل عليه كتابه وأيده بملك كريم هو واعظ الله في قلبه يأمره بأمر ربه ويبين له ما في طاعة عدوه من الهلاك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1702, 153, 3, 'وجعل له في مقابلة النفس الأمارة بالسوء نفْسًا مطمئنة، وأمده في مقابلة الهوى بنور العقل والبصيرة.', 0, 'النوع الرابع: الاستغفار. (ص294)', '', '', 'وجعل له في مقابلة النفس الأمارة بالسوء نفسا مطمئنة وأمده في مقابلة الهوى بنور العقل والبصيرة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1703, 153, 4, 'فإذا فرط منه زَلَّة؛ استدرك ذلك بالتوبة والاستغفار، والله تعالى بلطفه ورحمته يقبل مَن أقبلَ عليه، ويتوب على من تاب إليه.', 0, 'النوع الرابع: الاستغفار. (ص294)', '', '', 'فإذا فرط منه زلة استدرك ذلك بالتوبة والاستغفار والله تعالى بلطفه ورحمته يقبل من أقبل عليه ويتوب على من تاب إليه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1704, 153, 5, 'إن الاستغفار من أسباب محو الخطيئات، والعفو عن السيئات، وقد حفل الوحيان الشريفان بنصوص كثيرة تُعلي شأن الاستغفار، وتبين فضيلته، وأحكامه، وثمرته، وصِيَغَهُ.', 0, 'النوع الرابع: الاستغفار. (ص295)', '', '', 'إن الاستغفار من أسباب محو الخطيئات والعفو عن السيئات وقد حفل الوحيان الشريفان بنصوص كثيرة تعلي شأن الاستغفار وتبين فضيلته وأحكامه وثمرته وصيغه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1705, 153, 6, 'والاستغفار طلبُ أمرين في آنٍ واحد: ستر الذنب، والتجاوز عنه، ولا يُغني الأولُ عن الثاني؛ لأن سَتر الذنبِ لا يستلزم إسقاطَ العقوبة؛ فإن الله قد يستر على من يعاقِبُ ومن لا يعاقِب، والحاصل أن المغفرة هي وقاية شر الذنوب مع سَترها.', 0, 'النوع الرابع: الاستغفار. (ص295)', '', '', 'والاستغفار طلب أمرين في آن واحد ستر الذنب والتجاوز عنه ولا يغني الأول عن الثاني لأن ستر الذنب لا يستلزم إسقاط العقوبة فإن الله قد يستر على من يعاقب ومن لا يعاقب والحاصل أن المغفرة هي وقاية شر الذنوب مع سترها', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1706, 153, 7, 'من فضائلِ الاستغفار:', 0, '(ص296)', '', '', 'من فضائل الاستغفار', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1115, 153, 8, 'عن أبي سعيدٍ الخدري رضي الله عنه عن النبيِّ ﷺ قال: «قال إبليسُ: وعزَّتِك لا أبرحُ أُغوي عبادَك ما دامت أرواحُهم في أجسادِهم. فقال: وعِزَّتي وجلالي لا أزالُ أغفرُ لهم ما استغفَرُوني».', 0, 'من فضائل الاستغفار. (ص296)', '', '', 'عن أبي سعيد الخدري رضي الله عنه عن النبي قال «قال إبليس وعزتك لا أبرح أغوي عبادك ما دامت أرواحهم في أجسادهم فقال وعزتي وجلالي لا أزال أغفر لهم ما استغفروني»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1707, 153, 9, 'وعن أنسِ بنِ مالكٍ رضي الله عنه قال: قال رسولُ الله ﷺ: «قال اللهُ تبارك وتعالى: يا بْنَ آدمَ إنَّكَ ما دعوتَني ورجَوتَني غفَرتُ لَكَ على ما كانَ فيكَ ولا أُبالي، يا بْنَ آدمَ لو بلغَتْ ذنوبُكَ عَنانَ السَّماءِ، ثمَّ استغفرتَني غفرتُ لَكَ ولا أبالي، يا بْنَ آدمَ إنَّكَ لو أتيتَني بقُرابِ الأرضِ خطايا ثمَّ لقيتَني لا تشرِكُ بي شيئًا؛ لأتيتُكَ بقُرابِها مغفرةً».', 0, 'من فضائل الاستغفار. (ص296)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1708, 153, 10, 'وعن عُقبةَ بنِ عامرٍ الجُهَنيِّ رضي الله عنه، أنَّ رجُلًا أتى رسولَ الله ﷺ، فقال: يا رسولَ اللهِ، أَحَدُنا يُذْنِبُ، قالَ: «يُكْتَبُ عليه». قالَ: ثُمَّ يَسْتَغْفِرُ مِنهُ ويَتوبُ، قالَ: «يُغْفَرُ له، ويُتابُ عليه». قالَ: فيَعودُ ويُذْنِبُ، قالَ: «يُكْتَبُ عليه»، قالَ: ثُمَّ يَسْتَغْفِرُ مِنهُ ويَتوبُ، قالَ: «يُغْفَرُ له، ويُتابُ عليه»، قالَ: فَيَعودُ وَيُذْنِبُ، قالَ: «يُكْتَبُ عليه»، قالَ: ثُمَّ يَسْتَغْفِرُ مِنهُ ويَتوبُ، قالَ: «يُغْفَرُ له، ويُتابُ عليه، ولا يَمَلُّ اللهُ حتَّى تَمَلُّوا».', 0, 'من فضائل الاستغفار. (ص296–297)', '', '', 'وعن عقبة بن عامر الجهني رضي الله عنه أن رجلا أتى رسول الله فقال يا رسول الله أحدنا يذنب قال «يكتب عليه» قال ثم يستغفر منه ويتوب قال «يغفر له ويتاب عليه» قال فيعود ويذنب قال «يكتب عليه» قال ثم يستغفر منه ويتوب قال «يغفر له ويتاب عليه» قال فيعود ويذنب قال «يكتب عليه» قال ثم يستغفر منه ويتوب قال «يغفر له ويتاب عليه ولا يمل الله حتى تملوا»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1709, 153, 11, 'وعن جابرٍ رضي الله عنه، قال رسول الله ﷺ: «مرَّ رجلٌ ممَّن كان قبلَكم بجُمْجُمةٍ، فنظر إليها، فحدَّث نفسَه بشيءٍ ثمَّ قال: يا ربِّ! أنتَ أنتَ، وأنا أنا، أنت العوَّادُ بالمغفرةِ، وأنا العوَّادُ بالذُّنوبِ! وخرَّ للهِ ساجدًا، فقيل له: ارفَعْ رأسَك، فأنت العوَّادُ بالذُّنوبِ، وأنا العوَّادُ بالمغفرةِ، فرفع رأسَه، فغُفِر له».', 0, 'من فضائل الاستغفار. (ص297)', '', '', 'وعن جابر رضي الله عنه قال رسول الله «مر رجل ممن كان قبلكم بجمجمة فنظر إليها فحدث نفسه بشيء ثم قال يا رب! أنت أنت وأنا أنا أنت العواد بالمغفرة وأنا العواد بالذنوب! وخر لله ساجدا فقيل له ارفع رأسك فأنت العواد بالذنوب وأنا العواد بالمغفرة فرفع رأسه فغفر له»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1710, 153, 12, 'وعن أبي هريرةَ رضي الله عنه أنَّ رسولَ الله ﷺ قال: «إنَّ العبدَ إذا أخطأ خطيئةً، نُكِتَت في قلبِه نُكتةٌ سوداءُ، فإن هو نزَعَ واستَغفَرَ وتاب صُقِل قلبُه، وإن عاد زِيدَ فيها حتى تعلوَ على قلبِه، وهو الرَّانُ الذي ذكَر اللهُ تعالى: ﴿كَلَّاۖ بَلۡۜ رَانَ عَلَىٰ قُلُوبِهِم مَّا كَانُواْ يَكۡسِبُونَ﴾ [المطففين: ١٤]».', 0, 'من فضائل الاستغفار. (ص297–298)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1711, 153, 13, 'وعن فَضالةَ بنِ عُبَيدٍ رضي الله عنه، عنِ النبي ﷺ أنه قال: «العبدُ آمِنٌ مِن عَذابِ الله ما استغفَرَ اللهَ».', 0, 'من فضائل الاستغفار. (ص298)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1712, 153, 14, 'وعن أُمِّ المؤمنين عائشةَ رضي الله عنها، قالت: قيل: يا رسولَ الله، ماتت فلانةُ واستراحت! فَغَضِبَ رسولُ الله ﷺ، وقال: «إنَّما يستريحُ مَن غُفِرَ له».', 0, 'من فضائل الاستغفار. (ص298)', '', '', 'وعن أم المؤمنين عائشة رضي الله عنها قالت قيل يا رسول الله ماتت فلانة واستراحت! فغضب رسول الله وقال «إنما يستريح من غفر له»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1713, 153, 15, 'وعن الزُّبيرِ بنِ العوَّامِ رضي الله عنه، قال: قال رسول الله ﷺ: «مَنْ أَحَبَّ أنْ تَسُرَّهُ صحيفتُهُ فَلْيُكْثِرْ فيها مِنَ الاستغفارِ».', 0, 'من فضائل الاستغفار. (ص298)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1116, 153, 16, 'وعن عائشةَ رضي الله عنه قال رسول الله ﷺ: «طُوبَى لِمَنْ وَجَدَ في صحيفتِهِ استغفارًا كثيرًا».', 0, 'من فضائل الاستغفار. (ص298)', '', '', 'وعن عائشة رضي الله عنه قال رسول الله «طوبى لمن وجد في صحيفته استغفارا كثيرا»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1117, 153, 17, 'وعن أَغَرِّ مُزَيْنَةَ رضي الله عنه قال رسول الله ﷺ: «إنَّه لَيُغَانُ على قلبي، وإنِّي لأَسْتَغْفِرُ اللهَ في اليومِ مِئَةَ مَرَّةٍ».', 0, 'من فضائل الاستغفار. (ص299)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1714, 153, 18, 'ورُوِيَ عَنْ عَبْدِ الله بنِ عَبَّاسٍ رضي الله عنهما أنَّ رسولَ الله ﷺ قال: «مَن لَزِمَ الاستغفارَ، جَعَلَ اللهُ له مِن كُلِّ ضِيقٍ مَخرَجًا، ومِن كُلِّ هَمٍّ فَرَجًا، ورَزَقَه مِن حيث لا يَحتَسِبُ».', 0, 'من فضائل الاستغفار. (ص299)', '', '', 'وروي عن عبد الله بن عباس رضي الله عنهما أن رسول الله قال «من لزم الاستغفار جعل الله له من كل ضيق مخرجا ومن كل هم فرجا ورزقه من حيث لا يحتسب»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1715, 153, 19, 'وعنِ ابْنِ مَسْعودٍ رضي الله عنه قال: «كان رسولُ الله ﷺ يُعْجِبُه أن يدعوَ ثلاثًا، ويستغفر ثلاثًا».', 0, 'من فضائل الاستغفار. (ص299)', '', '', 'وعن ابن مسعود رضي الله عنه قال «كان رسول الله يعجبه أن يدعو ثلاثا ويستغفر ثلاثا»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1716, 153, 20, 'وعنه رضي الله عنه، قال رسول الله ﷺ: «مَنْ قالَ: (أَستَغفِرُ اللهَ الَّذي لا إلهَ إلَّا هو، الحَيُّ القَيُّومُ وأَتوبُ إليه) ثلاثًا؛ غُفِرَتْ ذُنوبُه، وإنْ كان فارًّا مِنَ الزَّحْفِ».', 0, 'من فضائل الاستغفار. (ص299)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1121, 153, 21, 'وعن أبي هريرةَ رضي الله عنه قال رسولُ الله ﷺ: «إنَّ أوفَقَ الدُّعاءِ أنْ يَقولَ الرَّجُلُ: اللَّهُمَّ أنتَ رَبِّي، وأنا عَبدُكَ، ظَلَمتُ نَفْسي واعتَرَفتُ بذَنبي، يا رَبِّ، فاغفِرْ لي ذَنبي، إنَّكَ أنتَ رَبِّي، إنَّه لا يَغفِرُ الذُّنوبَ إلَّا أنتَ».', 0, 'من فضائل الاستغفار. (ص300)', '', '', 'وعن أبي هريرة رضي الله عنه قال رسول الله «إن أوفق الدعاء أن يقول الرجل اللهم أنت ربي وأنا عبدك ظلمت نفسي واعترفت بذنبي يا رب فاغفر لي ذنبي إنك أنت ربي إنه لا يغفر الذنوب إلا أنت»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1120, 153, 22, 'وعن شدادِ بنِ أوسٍ رضي الله عنه أنَّ رسولَ الله ﷺ قال: «سَيِّدُ الاستغفارِ أن يقولَ العبدُ: (اللَّهُمَّ أنتَ ربِّي، لا إلَهَ إلَّا أنتَ، خلقتَني، وأنا عبدُكَ، وأنا على عَهدِكَ ووعدِكَ ما استطعتُ، أعوذُ بِكَ من شرِّ ما صنعتُ، أبوءُ لك بنعمتِكَ عليَّ، وأبوءُ بذنبي، فاغفر لي ذنوبي، فإنَّهُ لا يغفرُ الذُّنوبَ إلَّا أنتَ)، من قالَها من النهارِ موقنًا بها، فماتَ من يومِهِ قبلَ أن يُمْسِيَ؛ فهو من أهلِ الجنَّةِ، ومن قالَها من الليلِ وهو موقنٌ بها، فماتَ قبل أنْ يُصبِحَ؛ فهو من أهلِ الجنَّةِ».', 0, 'من فضائل الاستغفار. (ص300–301)', '', '', 'وعن شداد بن أوس رضي الله عنه أن رسول الله قال «سيد الاستغفار أن يقول العبد اللهم أنت ربي لا إله إلا أنت خلقتني وأنا عبدك وأنا على عهدك ووعدك ما استطعت أعوذ بك من شر ما صنعت أبوء لك بنعمتك علي وأبوء بذنبي فاغفر لي ذنوبي فإنه لا يغفر الذنوب إلا أنت من قالها من النهار موقنا بها فمات من يومه قبل أن يمسي فهو من أهل الجنة ومن قالها من الليل وهو موقن بها فمات قبل أن يصبح فهو من أهل الجنة»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1717, 71, 1, 'من صِيَغِ الاستغفار في القرآن الكريم', 0, '(ص302)', '', '', 'من صيغ الاستغفار في القرآن الكريم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1718, 71, 2, '﴿ رَبَّنَا ظَلَمۡنَآ أَنفُسَنَا وَإِن لَّمۡ تَغۡفِرۡ لَنَا وَتَرۡحَمۡنَا لَنَكُونَنَّ مِنَ ٱلۡخَٰسِرِينَ ﴾', 1, 'من صيغ الاستغفار في القرآن الكريم. [الأعراف: ٢٣]. (ص302)', '', '', '﴿ ربنا ظلمۡنا أنفسنا وإن لمۡ تغۡفرۡ لنا وترۡحمۡنا لنكونن من ٱلۡخسرين ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1719, 71, 3, '﴿ لَئِن لَّمۡ يَرۡحَمۡنَا رَبُّنَا وَيَغۡفِرۡ لَنَا لَنَكُونَنَّ مِنَ ٱلۡخَٰسِرِينَ ﴾', 1, 'من صيغ الاستغفار في القرآن الكريم. [الأعراف: ١٤٩]. (ص302)', '', '', '﴿ لئن لمۡ يرۡحمۡنا ربنا ويغۡفرۡ لنا لنكونن من ٱلۡخسرين ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1720, 71, 4, '﴿ رَبَّنَآ إِنَّنَآ ءَامَنَّا فَٱغۡفِرۡ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ ٱلنَّارِ ﴾', 1, 'من صيغ الاستغفار في القرآن الكريم. [آل عمران: ١٦]. (ص302)', '', '', '﴿ ربنا إننا ءامنا فٱغۡفرۡ لنا ذنوبنا وقنا عذاب ٱلنار ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1721, 71, 5, 'QuranText[(3:193:193)]', 1, 'من صيغ الاستغفار في القرآن الكريم. [آل عمران: ١٩٣]. (ص302)', '', '', '3193193', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1722, 71, 6, '﴿ رَبَّنَآ ءَامَنَّا فَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَا وَأَنتَ خَيۡرُ ٱلرَّٰحِمِينَ ﴾', 1, 'من صيغ الاستغفار في القرآن الكريم. [المؤمنون: ١٠٩]. (ص302)', '', '', '﴿ ربنا ءامنا فٱغۡفرۡ لنا وٱرۡحمۡنا وأنت خيۡر ٱلرحمين ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1723, 71, 7, '﴿ أَنتَ وَلِيُّنَا فَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَاۖ وَأَنتَ خَيۡرُ ٱلۡغَٰفِرِينَ ﴾', 1, 'من صيغ الاستغفار في القرآن الكريم. [الأعراف: ١٥٥]. (ص303)', '', '', '﴿ أنت ولينا فٱغۡفرۡ لنا وٱرۡحمۡناۖ وأنت خيۡر ٱلۡغفرين ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1724, 71, 8, '﴿ سَمِعۡنَا وَأَطَعۡنَاۖ غُفۡرَانَكَ رَبَّنَا وَإِلَيۡكَ ٱلۡمَصِيرُ ﴾', 1, 'من صيغ الاستغفار في القرآن الكريم. [البقرة: ٢٨٥]. (ص303)', '', '', '﴿ سمعۡنا وأطعۡناۖ غفۡرانك ربنا وإليۡك ٱلۡمصير ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1725, 71, 9, '﴿ رَبَّنَا لَا تُؤَاخِذۡنَآ إِن نَّسِينَآ أَوۡ أَخۡطَأۡنَاۚ رَبَّنَا وَلَا تَحۡمِلۡ عَلَيۡنَآ إِصۡرٗا كَمَا حَمَلۡتَهُۥ عَلَى ٱلَّذِينَ مِن قَبۡلِنَاۚ رَبَّنَا وَلَا تُحَمِّلۡنَا مَا لَا طَاقَةَ لَنَا بِهِۦۖ وَٱعۡفُ عَنَّا وَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَآۚ أَنتَ مَوۡلَىٰنَا فَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ ﴾', 1, 'من صيغ الاستغفار في القرآن الكريم. [البقرة: ٢٨٦]. (ص303)', '', '', '﴿ ربنا لا تؤاخذۡنا إن نسينا أوۡ أخۡطأۡناۚ ربنا ولا تحۡملۡ عليۡنا إصۡرا كما حملۡتهۥ على ٱلذين من قبۡلناۚ ربنا ولا تحملۡنا ما لا طاقة لنا بهۦۖ وٱعۡف عنا وٱغۡفرۡ لنا وٱرۡحمۡناۚ أنت موۡلىنا فٱنصرۡنا على ٱلۡقوۡم ٱلۡكفرين ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1726, 71, 10, '﴿ رَبَّنَا ٱغۡفِرۡ لَنَا ذُنُوبَنَا وَإِسۡرَافَنَا فِيٓ أَمۡرِنَا وَثَبِّتۡ أَقۡدَامَنَا وَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ ﴾', 1, 'من صيغ الاستغفار في القرآن الكريم. [آل عمران: ١٤٧]. (ص303)', '', '', '﴿ ربنا ٱغۡفرۡ لنا ذنوبنا وإسۡرافنا في أمۡرنا وثبتۡ أقۡدامنا وٱنصرۡنا على ٱلۡقوۡم ٱلۡكفرين ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1727, 71, 11, '﴿ رَبَّنَا وَسِعۡتَ كُلَّ شَيۡءٖ رَّحۡمَةٗ وَعِلۡمٗا فَٱغۡفِرۡ لِلَّذِينَ تَابُواْ وَٱتَّبَعُواْ سَبِيلَكَ وَقِهِمۡ عَذَابَ ٱلۡجَحِيمِ ﴾', 1, 'من صيغ الاستغفار في القرآن الكريم. [غافر: ٧]. (ص303)', '', '', '﴿ ربنا وسعۡت كل شيۡء رحۡمة وعلۡما فٱغۡفرۡ للذين تابوا وٱتبعوا سبيلك وقهمۡ عذاب ٱلۡجحيم ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1728, 71, 12, 'QuranText[(60:5:5)]', 1, 'من صيغ الاستغفار في القرآن الكريم. [الممتحنة: ٥]. (ص303)', '', '', '6055', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1729, 71, 13, 'QuranText[(14:41:41)]', 1, 'من صيغ الاستغفار في القرآن الكريم. [إبراهيم: ٤١]. (ص304)', '', '', '144141', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1730, 71, 14, 'QuranText[(71:28:28)]', 1, 'من صيغ الاستغفار في القرآن الكريم. [نوح: ٢٨]. (ص304)', '', '', '712828', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1731, 71, 15, '﴿ رَبَّنَا ٱغۡفِرۡ لَنَا وَلِإِخۡوَٰنِنَا ٱلَّذِينَ سَبَقُونَا بِٱلۡإِيمَٰنِ وَلَا تَجۡعَلۡ فِي قُلُوبِنَا غِلّٗا لِّلَّذِينَ ءَامَنُواْ رَبَّنَآ إِنَّكَ رَءُوفٞ رَّحِيمٌ ﴾', 1, 'من صيغ الاستغفار في القرآن الكريم. [الحشر: ١٠]. (ص304)', '', '', '﴿ ربنا ٱغۡفرۡ لنا ولإخۡوننا ٱلذين سبقونا بٱلۡإيمن ولا تجۡعلۡ في قلوبنا غلا للذين ءامنوا ربنا إنك رءوف رحيم ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1732, 71, 16, '﴿ رَبِّ إِنِّي ظَلَمۡتُ نَفۡسِي فَٱغۡفِرۡ لِي ﴾', 1, 'من صيغ الاستغفار في القرآن الكريم. [القصص: ١٦]. (ص304)', '', '', '﴿ رب إني ظلمۡت نفۡسي فٱغۡفرۡ لي ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1733, 71, 17, '﴿ رَّبِّ ٱغۡفِرۡ وَٱرۡحَمۡ وَأَنتَ خَيۡرُ ٱلرَّٰحِمِينَ ﴾', 1, 'من صيغ الاستغفار في القرآن الكريم. [المؤمنون: ١١٨]. (ص304)', '', '', '﴿ رب ٱغۡفرۡ وٱرۡحمۡ وأنت خيۡر ٱلرحمين ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1734, 71, 18, 'رَبِّ اغفرْ لي ﴿خَطِيٓـَٔتِي يَوۡمَ ٱلدِّينِ﴾.', 1, 'من صيغ الاستغفار في القرآن الكريم. [جزء من الآية (٨٢) من سورة الشعراء]. (ص304)', '', '', 'رب اغفر لي ﴿خطيتي يوۡم ٱلدين﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1735, 71, 19, '﴿ لَّآ إِلَٰهَ إِلَّآ أَنتَ سُبۡحَٰنَكَ إِنِّي كُنتُ مِنَ ٱلظَّٰلِمِينَ ﴾', 1, 'من صيغ الاستغفار في القرآن الكريم. [الأنبياء: ٨٧]. (ص304)', '', '', '﴿ لا إله إلا أنت سبۡحنك إني كنت من ٱلظلمين ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1736, 71, 20, 'اللهُمَّ إنِّي أستغفِرُكَ فاغفِرْ لي، وأتوبُ إليكَ، فَتُبْ عَلَيَّ.', 1, 'من صيغ الاستغفار في القرآن الكريم. (ص305)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1737, 72, 1, 'من صِيَغِ الاستغفار في السُّنَّةِ الشَّريفةِ', 0, '(ص306)', '', '', 'من صيغ الاستغفار في السنة الشريفة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1738, 72, 2, 'أستغفِرُ الله، وأتوبُ إليه.', 1, 'من صيغ الاستغفار في السنة الشريفة. [كثيرًا]. (ص306)', '', '', 'أستغفر الله وأتوب إليه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1739, 72, 3, 'ربِّ اغفِرْ لي، وتُبْ عَلَيَّ، إنَّك أنتَ التواب الرحيم.', 100, 'من صيغ الاستغفار في السنة الشريفة. [مئة مرة]. (ص306)', '', '', 'رب اغفر لي وتب علي إنك أنت التواب الرحيم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1740, 72, 4, 'سبحان الله وبحمده، أستغفِرُ الله وأتوبُ إليه.', 1, 'من صيغ الاستغفار في السنة الشريفة. (ص306)', '', '', 'سبحان الله وبحمده أستغفر الله وأتوب إليه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1741, 72, 5, 'يا ربِّ، أنتَ أنتَ، وأنا أنا، أنتَ العوَّادُ بالمغفرة، وأنا العوَّادُ بالذنوب.', 1, 'من صيغ الاستغفار في السنة الشريفة. (ص306)', '', '', 'يا رب أنت أنت وأنا أنا أنت العواد بالمغفرة وأنا العواد بالذنوب', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1742, 72, 6, 'اللهم اغفِر لي، وارحمني، وارزقني، واهدني، وعافني.', 1, 'من صيغ الاستغفار في السنة الشريفة. (ص306)', '', '', 'اللهم اغفر لي وارحمني وارزقني واهدني وعافني', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1743, 72, 7, 'أستغفِرُ الله الذي لا إله إلا هو الحيُّ القيُّومُ، وأتوبُ إليه.', 1, 'من صيغ الاستغفار في السنة الشريفة. (ص306)', '', '', 'أستغفر الله الذي لا إله إلا هو الحي القيوم وأتوب إليه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1744, 72, 8, 'اللهم اغفِرْ لي ما قدَّمتُ وما أخَّرتُ، وما أسررتُ وما أعلنتُ، وما أنتَ أعلمُ به مني، إنَّك أنت المُقدِّمُ والمؤخِّرُ، لا إله إلا أنتَ.', 1, 'من صيغ الاستغفار في السنة الشريفة. (ص307)', '', '', 'اللهم اغفر لي ما قدمت وما أخرت وما أسررت وما أعلنت وما أنت أعلم به مني إنك أنت المقدم والمؤخر لا إله إلا أنت', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1745, 72, 9, 'لا إله إلا أنت، إني قد ظلمتُ نفسي، فاغفِرْ لي ذنوبي، إنه لا يغفِرُ الذنوبَ إلا أنتَ.', 1, 'من صيغ الاستغفار في السنة الشريفة. (ص307)', '', '', 'لا إله إلا أنت إني قد ظلمت نفسي فاغفر لي ذنوبي إنه لا يغفر الذنوب إلا أنت', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1746, 72, 10, 'اللهُمَّ أنتَ رَبِّي، لا إله إلا أنتَ، خَلَقْتَني وأنا عبدُكَ، وأنا على عهدِكَ وَوَعْدِكَ ما استطعتُ، أعوذُ بِكَ مِنْ شَرِّ ما صَنعتُ، أَبُوءُ لَكَ بِنعمَتِكَ عَلَيَّ، وأبوءُ بِذَنبي، فاغفِر لي، فإنه لا يغفرُ الذُّنوبَ إلَّا أنتَ.', 1, 'من صيغ الاستغفار في السنة الشريفة. (ص307)', '', '', 'اللهم أنت ربي لا إله إلا أنت خلقتني وأنا عبدك وأنا على عهدك ووعدك ما استطعت أعوذ بك من شر ما صنعت أبوء لك بنعمتك علي وأبوء بذنبي فاغفر لي فإنه لا يغفر الذنوب إلا أنت', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1747, 72, 11, 'اللهم اغفِرْ لي خطيئتي وجهلي، وإسرافي في أمري، وما أنتَ أعلمُ به منِّي، اللهم اغفِرْ لي جِدِّي وهَزْلي، وخطئي وعَمْدِي، وكلُّ ذلك عندي، اللهم اغفِر لي ما قدَّمتُ وما أخَّرتُ، وما أسررتُ وما أعلنتُ، وما أنتَ أعلمُ به منِّي، أنتَ المُقَدِّمُ وأنتَ المؤخِّرُ، وأنتَ على كُلِّ شيءٍ قدير.', 1, 'من صيغ الاستغفار في السنة الشريفة. (ص307)', '', '', 'اللهم اغفر لي خطيئتي وجهلي وإسرافي في أمري وما أنت أعلم به مني اللهم اغفر لي جدي وهزلي وخطئي وعمدي وكل ذلك عندي اللهم اغفر لي ما قدمت وما أخرت وما أسررت وما أعلنت وما أنت أعلم به مني أنت المقدم وأنت المؤخر وأنت على كل شيء قدير', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1748, 72, 12, 'اللهم أنتَ ربي، وأنا عبدُكَ، ظلمتُ نفسي، واعترفتُ بذنبي يا رَبِّ، فاغفِرْ لي ذنبي، إنَّكَ أنتَ ربي، إنه لا يغفِرُ الذنبَ إلا أنتَ.', 1, 'من صيغ الاستغفار في السنة الشريفة. (ص308)', '', '', 'اللهم أنت ربي وأنا عبدك ظلمت نفسي واعترفت بذنبي يا رب فاغفر لي ذنبي إنك أنت ربي إنه لا يغفر الذنب إلا أنت', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1749, 72, 13, 'ومن أسباب مغفرة الذنوب: كثرة الصلاة على رسول الله ﷺ؛ لأنَّ أُبَيَّ بنَ كعبٍ رضي الله عنه لَمَّا قال للنبي ﷺ: «أجعلُ لكَ صلاتي كلَّها؟» قال له النبيُّ ﷺ: «إذَن تُكفَى همَّكَ، وَيُغْفَرُ لك ذنبُك».', 0, 'من صيغ الاستغفار في السنة الشريفة. (ص308)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1750, 154, 1, 'النوع الخامس: وِرْدُ الباقياتِ الصَّالحات', 0, '(ص309)', '', '', 'النوع الخامس ورد الباقيات الصالحات', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1751, 154, 2, 'الباقيات الصالحات -التي وَرَدَ ذِكرُها في قوله تبارك وتعالى: ﴿ٱلۡمَالُ وَٱلۡبَنُونَ زِينَةُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَٱلۡبَٰقِيَٰتُ ٱلصَّٰلِحَٰتُ خَيۡرٌ عِندَ رَبِّكَ ثَوَابٗا وَخَيۡرٌ أَمَلٗا﴾ [الكهف: ٤٩]، وفي قوله عَزَّ وَجَلَّ: ﴿وَيَزِيدُ ٱللَّهُ ٱلَّذِينَ ٱهۡتَدَوۡاْ هُدٗىۗ وَٱلۡبَٰقِيَٰتُ ٱلصَّٰلِحَٰتُ خَيۡرٌ عِندَ رَبِّكَ ثَوَابٗا وَخَيۡرٞ مَّرَدًّا﴾ [مريم: ٧٦]- هي جميع أعمال الخير، كما جاء عن ابن عبَّاسٍ رضي الله عنهما في قوله: ﴿وَٱلۡبَٰقِيَٰتُ ٱلصَّٰلِحَٰتُ﴾، قال: «هي ذِكْرُ الله؛ قولُ: لا إله إلا الله، والله أكبرُ، وسبحانَ الله، والحمدُ لله، وتباركَ الله، ولا حول ولا قوَّةَ إلا بالله، وأستغفِرُ الله، وصلَّى اللهُ على رسولِ الله، والصيامُ، والصلاةُ، والحجُّ، والصدقةُ، والعِتْقُ، والجهادُ، والصلةُ، وجميعُ أعمالِ الحسناتِ، وهُنَّ الباقياتُ الصالحاتُ، التي تبقى لأهلها في الجنة ما دامتِ السماواتُ والأرض».', 0, 'النوع الخامس: وِرْدُ الباقياتِ الصَّالحات. (ص309)', '', '', 'الباقيات الصالحات -التي ورد ذكرها في قوله تبارك وتعالى ﴿ٱلۡمال وٱلۡبنون زينة ٱلۡحيوة ٱلدنۡياۖ وٱلۡبقيت ٱلصلحت خيۡر عند ربك ثوابا وخيۡر أملا﴾ الكهف ٤٩ وفي قوله عز وجل ﴿ويزيد ٱلله ٱلذين ٱهۡتدوۡا هدىۗ وٱلۡبقيت ٱلصلحت خيۡر عند ربك ثوابا وخيۡر مردا﴾ مريم ٧٦ - هي جميع أعمال الخير كما جاء عن ابن عباس رضي الله عنهما في قوله ﴿وٱلۡبقيت ٱلصلحت﴾ قال «هي ذكر الله قول لا إله إلا الله والله أكبر وسبحان الله والحمد لله وتبارك الله ولا حول ولا قوة إلا بالله وأستغفر الله وصلى الله على رسول الله والصيام والصلاة والحج والصدقة والعتق والجهاد والصلة وجميع أعمال الحسنات وهن الباقيات الصالحات التي تبقى لأهلها في الجنة ما دامت السماوات والأرض»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1752, 154, 3, 'وسُمِّيَتْ باقياتٍ؛ لأنها تبقى لأهلها في الجنة في مقابلة الفانيات الزائلات، التي هي زينةُ الدنيا، وقد قال تعالى: ﴿بَلۡ تُؤۡثِرُونَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا ١٦ وَٱلۡأٓخِرَةُ خَيۡرٞ وَأَبۡقَىٰٓ﴾ [الأعلى: ١٦، ١٧].', 0, 'النوع الخامس: وِرْدُ الباقياتِ الصَّالحات. (ص310)', '', '', 'وسميت باقيات لأنها تبقى لأهلها في الجنة في مقابلة الفانيات الزائلات التي هي زينة الدنيا وقد قال تعالى ﴿بلۡ تؤۡثرون ٱلۡحيوة ٱلدنۡيا ١٦ وٱلۡأخرة خيۡر وأبۡقى﴾ الأعلى ١٦ ١٧', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1753, 154, 4, 'ومع ذلك سمَّى رسولُ الله ﷺ قولَ العبد: «سبحانَ الله، والحمدُ لله، ولا إله إلا الله، والله أكبر» -وزاد في بعض الروايات: «ولا حولَ ولا قوَّةَ إلا بالله»- الباقياتِ الصالحاتِ إشارةً إلى أنَّ هذه الكلماتِ الخمسَ أَوْلَى ما يُطلَقُ عليه الباقيات الصالحات لما ثبت لهن من الفضائل العظيمة:', 0, 'النوع الخامس: وِرْدُ الباقياتِ الصَّالحات. (ص310)', '', '', 'ومع ذلك سمى رسول الله قول العبد «سبحان الله والحمد لله ولا إله إلا الله والله أكبر» -وزاد في بعض الروايات «ولا حول ولا قوة إلا بالله»- الباقيات الصالحات إشارة إلى أن هذه الكلمات الخمس أولى ما يطلق عليه الباقيات الصالحات لما ثبت لهن من الفضائل العظيمة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1124, 154, 5, 'عن أبي هريرةَ رضي الله عنه أنَّ رسولَ الله ﷺ قال: «خُذوا جُنَّتَكم»، قالوا: يا رسولَ اللهِ! أمِن عدوٍّ قد حضر؟ قال: «لا، ولكن جُنَّتكم من النَّارِ، قولوا: (سبحانَ اللهِ، والحمدُ لله، ولا إله إلا اللهُ، واللهُ أكبرُ)؛ فإنهن يأتين يومَ القيامةِ مجنَّباتٌ ومُعقِّباتٌ، وهنَّ الباقياتُ الصالحاتُ».', 0, 'النوع الخامس: وِرْدُ الباقياتِ الصَّالحات. (ص310–311)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1754, 154, 6, 'وعنه رضي الله عنه أنَّ رسولَ الله ﷺ قال: «سبحانَ اللهِ، والحمدُ لله، ولا إله إلا الله، والله أكبرُ، من الباقيات الصالحات».', 0, 'النوع الخامس: وِرْدُ الباقياتِ الصَّالحات. (ص311)', '', '', 'وعنه رضي الله عنه أن رسول الله قال «سبحان الله والحمد لله ولا إله إلا الله والله أكبر من الباقيات الصالحات»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1755, 154, 7, 'وعن سَمُرةَ بنِ جُنْدُبٍ رضي الله عنه قال: قال رسولُ الله ﷺ: «أربعٌ هُنَّ مِن أطيَبِ الكلامِ، وهُنَّ من القرآنِ، ولا يضرك بأيِّهِنَّ بدأتَ: سبحانَ الله، والحمدُ لله، ولا إله إلَّا الله، والله أكبر» الحديث.', 0, 'النوع الخامس: وِرْدُ الباقياتِ الصَّالحات. (ص311)', '', '', 'وعن سمرة بن جندب رضي الله عنه قال قال رسول الله «أربع هن من أطيب الكلام وهن من القرآن ولا يضرك بأيهن بدأت سبحان الله والحمد لله ولا إله إلا الله والله أكبر» الحديث', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1132, 154, 8, 'وعن أبي هريرةَ رضي الله عنه قال: قال رسول الله ﷺ: «لأن أقولَ: سبحانَ الله، والحمدُ لله، ولا إله إلا الله، والله أكبر، أحبُّ إليَّ مما طَلَعَتْ عليه الشمسُ».', 0, 'النوع الخامس: وِرْدُ الباقياتِ الصَّالحات. (ص311)', '', '', 'وعن أبي هريرة رضي الله عنه قال قال رسول الله «لأن أقول سبحان الله والحمد لله ولا إله إلا الله والله أكبر أحب إلي مما طلعت عليه الشمس»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1756, 154, 9, 'ومن فضائلها: أنها كفَّارةٌ للذنوب والخطايا:', 0, '(ص312)', '', '', 'ومن فضائلها أنها كفارة للذنوب والخطايا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1123, 154, 10, 'فعن عبد الله بن عمر رضي الله عنهما قال رسولُ الله ﷺ: «ما على الأرضِ رجلٌ يقول: لا إله إلا الله، والله أكبر، وسبحان الله، والحمدُ لله، ولا حولَ ولا قوَّةَ إلا بالله، إلا كُفِّرَت عَنهُ ذُنُوبُه، ولو كانت أكثرَ مِنْ زَبَدِ البحرِ».', 0, 'ومن فضائلها: أنها كفارة للذنوب والخطايا. (ص312)', '', '', 'فعن عبد الله بن عمر رضي الله عنهما قال رسول الله «ما على الأرض رجل يقول لا إله إلا الله والله أكبر وسبحان الله والحمد لله ولا حول ولا قوة إلا بالله إلا كفرت عنه ذنوبه ولو كانت أكثر من زبد البحر»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1757, 154, 11, 'وعن أنسٍ رضي الله عنه أنَّ رسولَ الله ﷺ مَرَّ بشجرةٍ يابسةِ الورق، فضربها بعصاه، فتناثر الورق، فقال: «إنَّ الحمدَ لله، وسبحانَ الله، ولا إله إلا الله، والله أكبر، لَتُسَاقِطُ من ذنوبِ العبدِ كما تَسَاقَطَ ورقُ هذه الشجرةِ».', 0, 'ومن فضائلها: أنها كفارة للذنوب والخطايا. (ص312)', '', '', 'وعن أنس رضي الله عنه أن رسول الله مر بشجرة يابسة الورق فضربها بعصاه فتناثر الورق فقال «إن الحمد لله وسبحان الله ولا إله إلا الله والله أكبر لتساقط من ذنوب العبد كما تساقط ورق هذه الشجرة»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1758, 154, 12, 'وعن عبد الله بن مسعودٍ رضي الله عنه قال: قال رسول الله ﷺ: «إنَّ اللهَ قسم بينكم أخلاقَكم كما قسم بينكم أرزاقَكم، وإنَّ اللهَ يُعطي الدُّنيا من يُحِبُّ ومن لا يُحبُّ، ولا يُعطي الإيمانَ إلَّا من أحبَّ، فمن ضنَّ بالمالِ أن يُنفِقَه، وخاف العدوَّ أن يُجاهِدَه، وهاب اللَّيلَ أن يُكابِدَه، فليُكثِر من قولِ: سبحانَ اللهِ، والحمدُ للهِ، ولا إلهَ إلَّا اللهُ، واللهُ أكبرُ».', 0, 'ومن فضائلها: أنها كفارة للذنوب والخطايا. (ص312–313)', '', '', 'وعن عبد الله بن مسعود رضي الله عنه قال قال رسول الله «إن الله قسم بينكم أخلاقكم كما قسم بينكم أرزاقكم وإن الله يعطي الدنيا من يحب ومن لا يحب ولا يعطي الإيمان إلا من أحب فمن ضن بالمال أن ينفقه وخاف العدو أن يجاهده وهاب الليل أن يكابده فليكثر من قول سبحان الله والحمد لله ولا إله إلا الله والله أكبر»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1759, 154, 13, 'وعنه رضي الله عنه أنَّ رسولَ الله ﷺ قال: «لَقِيتُ إبراهيمَ ليلةَ أُسرِيَ بي، فقال: يا محمدُ، أقريءْ أُمَّتَك مني السلامَ، وأَخْبِرْهُمْ أنَّ الجنةَ طيبةُ التربةِ، عذبةُ الماءِ، وأنها قِيعانٌ، وأنَّ غِراسَها سبحانَ اللهِ، والحمدُ للهِ، ولا إلهَ إلا اللهُ، واللهُ أكبرُ».', 0, 'ومن فضائلها: أنها كفارة للذنوب والخطايا. (ص313)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1760, 154, 14, 'قال العلَّامةُ الصنعاني رحمه الله: «والأحاديث في فضلِ هذه الكلماتِ مجموعة ومتفرِّقة بحرٌ لا تُنْزِفه الدِّلاءُ، ولا يُنْقِصُه الإملاءُ».', 0, 'ومن فضائلها: أنها كفارة للذنوب والخطايا. (ص313)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1761, 176, 1, 'النوع السادس: وِرْدُ التَّسْبيح', 0, '(ص314)', '', '', 'النوع السادس ورد التسبيح', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1762, 176, 2, 'التسبيح هو تنزيه الله تعالى عما لا يليق به في ذاته وصفاته وأفعاله، وهو ثناء عليه سبحانه يتضمن التعظيم والتنزيه.', 0, 'النوع السادس: وِرْدُ التَّسْبيح. (ص314)', '', '', 'التسبيح هو تنزيه الله تعالى عما لا يليق به في ذاته وصفاته وأفعاله وهو ثناء عليه سبحانه يتضمن التعظيم والتنزيه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1763, 176, 3, 'والتسبيح حَقٌّ من حقوق الله تعالى على العباد يجب عليهم إفرادُه به، وقد أمر الله عبادَه بهذه العبادة العظيمة تارةً أمرَ إيجابٍ، وأخرى أمرَ استحباب، وخصَّه الله بأنواع من الفضل، ووعد عليه الجزيلَ من الأجر.', 0, 'النوع السادس: وِرْدُ التَّسْبيح. (ص314)', '', '', 'والتسبيح حق من حقوق الله تعالى على العباد يجب عليهم إفراده به وقد أمر الله عباده بهذه العبادة العظيمة تارة أمر إيجاب وأخرى أمر استحباب وخصه الله بأنواع من الفضل ووعد عليه الجزيل من الأجر', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1764, 176, 4, 'والتسبيح عبادةٌ مشتركة يؤدِّيها جميعُ الكائنات في الأرض والسماوات، وهو عبادة لا تنتهي بانقضاء الدنيا، بل هي مستمرة باقية في الجنة، دائمة بدوام أهلها الذين «يُلْهَمُونَ التسبيحَ والتحميد كما تُلهَمون النَّفَسَ»، ﴿دَعۡوَىٰهُمۡ فِيهَا سُبۡحَٰنَكَ ٱللَّهُمَّ وَتَحِيَّتُهُمۡ فِيهَا سَلَٰمٞۚ وَءَاخِرُ دَعۡوَىٰهُمۡ أَنِ ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ﴾ [يونس: ١٠]، وهم يتلذذون ويتنعمون بكونهم «يُسَبِّحون اللهَ بُكرةً وعشيًّا» تَلَذُّذًا يفوق تلذذَهم بالمآكِلِ والمشارِبِ والمناكح.', 0, 'النوع السادس: وِرْدُ التَّسْبيح. (ص314–315)', '', '', 'والتسبيح عبادة مشتركة يؤديها جميع الكائنات في الأرض والسماوات وهو عبادة لا تنتهي بانقضاء الدنيا بل هي مستمرة باقية في الجنة دائمة بدوام أهلها الذين «يلهمون التسبيح والتحميد كما تلهمون النفس» ﴿دعۡوىهمۡ فيها سبۡحنك ٱللهم وتحيتهمۡ فيها سلمۚ وءاخر دعۡوىهمۡ أن ٱلۡحمۡد لله رب ٱلۡعلمين﴾ يونس ١٠ وهم يتلذذون ويتنعمون بكونهم «يسبحون الله بكرة وعشيا» تلذذا يفوق تلذذهم بالمآكل والمشارب والمناكح', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1765, 176, 5, 'ومما يدل على فضل التسبيح وجلالةِ قدرِه عند الله عَزَّ وَجَلَّ أن التسبيح بتصاريفه المختلفة قد جاء في كتاب الله المجيد سبعًا وثمانين مرة.', 0, 'النوع السادس: وِرْدُ التَّسْبيح. (ص315)', '', '', 'ومما يدل على فضل التسبيح وجلالة قدره عند الله عز وجل أن التسبيح بتصاريفه المختلفة قد جاء في كتاب الله المجيد سبعا وثمانين مرة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1766, 176, 6, 'والتسبيح ليس فقط تنزيهًا لله عن النقائص والعيوب والآفات، لكنه أيضًا يتضمن أمرًا وجوديًا هو كمال، فالتسبيح نفي يتضمن إثباتًا، وسَلْبٌ يستلزم إيجابًا، والتنزيه الذي دلَّ عليه التسبيح مقصودُه نفيُ ما يناقض الكمالَ، فإذا نُفِيَ النقيضُ الذي هو النقص والعيب؛ لزم ثبوت النقيض الآخر الذي هو الكمال والمدح.', 0, 'النوع السادس: وِرْدُ التَّسْبيح. (ص315)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1767, 176, 7, 'والدليل على أن التسبيحَ تعظيمٌ ومدحٌ وثناءٌ لله تعالى قولُ رسولِ الله ﷺ: «فأما الركوع فعظِّموا فيه الربَّ عَزَّ وَجَلَّ»، وذلك يكون بالتسبيح مثل: «سبحان ربي العظيم»، و«سبحان ربي العظيم وبحمده» و«سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي»، ولما سُئل أمير المؤمنين علي رضي الله عنه عن «سبحان الله»؛ قال: «تعظيمُ جَلالِ الله».', 0, 'النوع السادس: وِرْدُ التَّسْبيح. (ص315–316)', '', '', 'والدليل على أن التسبيح تعظيم ومدح وثناء لله تعالى قول رسول الله «فأما الركوع فعظموا فيه الرب عز وجل» وذلك يكون بالتسبيح مثل «سبحان ربي العظيم» و«سبحان ربي العظيم وبحمده» و«سبحانك اللهم ربنا وبحمدك اللهم اغفر لي» ولما سئل أمير المؤمنين علي رضي الله عنه عن «سبحان الله» قال «تعظيم جلال الله»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1768, 176, 8, 'وقال أيضًا رضي الله عنه: «سبحان الله: كلمة أحبها الله لنفسه، ورَضِيَها، وأحبَّ أن تُقال».', 0, 'النوع السادس: وِرْدُ التَّسْبيح. (ص316)', '', '', 'وقال أيضا رضي الله عنه «سبحان الله كلمة أحبها الله لنفسه ورضيها وأحب أن تقال»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1769, 176, 9, 'وسأل رجلٌ ميمونَ بنَ مِهران عن «سبحان الله»، فقال: «اسم يُعَظَّمُ الله به، ويُحاشَى به من السوء».', 0, 'النوع السادس: وِرْدُ التَّسْبيح. (ص316)', '', '', 'وسأل رجل ميمون بن مهران عن «سبحان الله» فقال «اسم يعظم الله به ويحاشى به من السوء»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1770, 176, 10, 'وقال ابن دُرَيْد: «سبَّح الرجلُ تسبيحًا: عظَّم الله ومجَّده».', 0, 'النوع السادس: وِرْدُ التَّسْبيح. (ص316)', '', '', 'وقال ابن دريد «سبح الرجل تسبيحا عظم الله ومجده»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1771, 176, 11, 'وقال الماوردي: «التسبيح في كلامهم: التنزيه من السوء على جهة التعظيم».', 0, 'النوع السادس: وِرْدُ التَّسْبيح. (ص316)', '', '', 'وقال الماوردي «التسبيح في كلامهم التنزيه من السوء على جهة التعظيم»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1772, 176, 12, 'وقال أيضًا: «التسبيح من السَّبْح في التعظيم، وهو الجري فيه إلى أبعد الغايات».', 0, 'النوع السادس: وِرْدُ التَّسْبيح. (ص316)', '', '', 'وقال أيضا «التسبيح من السبح في التعظيم وهو الجري فيه إلى أبعد الغايات»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1773, 176, 13, 'وقال عُبَيْدُ بْنُ عُمَيْر رحمه الله: «تسبيحةٌ بحَمْدِ الله في صحيفة المؤمن خيرٌ من أن تسير أو تسيل مَعَهُ جبالُ الدُّنْيا ذهبًا».', 0, 'النوع السادس: وِرْدُ التَّسْبيح. (ص317)', '', '', 'وقال عبيد بن عمير رحمه الله «تسبيحة بحمد الله في صحيفة المؤمن خير من أن تسير أو تسيل معه جبال الدنيا ذهبا»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1774, 74, 1, 'صِيَغُ التَّسبيحِ في القُرآنِ والسُّنَّة', 0, '(ص318)', '', '', 'صيغ التسبيح في القرآن والسنة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1775, 74, 2, 'أولًا: من صِيَغِ التسبيح المفردة:', 0, '(ص318)', '', '', 'أولا من صيغ التسبيح المفردة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1776, 74, 3, '﴿ سُبۡحَٰنَ ٱللَّهِ ﴾', 1, 'أولًا: من صيغ التسبيح المفردة. [جزء من الآية (١٠٨) سورة يوسف]. (ص318)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1777, 74, 4, '﴿ سُبۡحَانَ رَبِّي ﴾', 1, 'أولًا: من صيغ التسبيح المفردة. [جزء من الآية (٩٣) سورة الإسراء]. (ص318)', '', '', '﴿ سبۡحان ربي ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1778, 74, 5, '﴿ سُبۡحَٰنَ ٱللَّهِ رَبِّ ٱلۡعَٰلَمِينَ ﴾', 1, 'أولًا: من صيغ التسبيح المفردة. [جزء من الآية (٨) سورة النمل]. (ص318)', '', '', '﴿ سبۡحن ٱلله رب ٱلۡعلمين ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1779, 74, 6, '﴿ سُبۡحَٰنَ ٱللَّهِ وَتَعَٰلَىٰ عَمَّا يُشۡرِكُونَ ﴾', 1, 'أولًا: من صيغ التسبيح المفردة. [جزء من الآية (٦٨) سورة القصص]. (ص318)', '', '', '﴿ سبۡحن ٱلله وتعلى عما يشۡركون ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1780, 74, 7, '﴿ سُبۡحَٰنَ ٱللَّهِ رَبِّ ٱلۡعَرۡشِ عَمَّا يَصِفُونَ ﴾', 1, 'أولًا: من صيغ التسبيح المفردة. [جزء من الآية (٢٢) سورة الأنبياء]. (ص318)', '', '', '﴿ سبۡحن ٱلله رب ٱلۡعرۡش عما يصفون ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1781, 74, 8, 'سُبحانك ما أعظَمَكَ ربَّنا.', 1, 'أولًا: من صيغ التسبيح المفردة. (ص318)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1782, 74, 9, 'ثانيًا: من الصيغ المقرونة:', 0, '(ص319)', '', '', 'ثانيا من الصيغ المقرونة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1783, 74, 10, 'إنَّ التسبيحَ المفرد يدل على التعظيم والمدح والكمال، فإذا وَرَدَ مقرونًا كانت له دلالة أخرى في إثبات الكمال والثناء على الله تعالى.', 0, 'ثانيًا: من الصيغ المقرونة. (ص319)', '', '', 'إن التسبيح المفرد يدل على التعظيم والمدح والكمال فإذا ورد مقرونا كانت له دلالة أخرى في إثبات الكمال والثناء على الله تعالى', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1784, 74, 11, '١- اقتران التسبيح بالحمد:', 0, '(ص319)', '', '', '١- اقتران التسبيح بالحمد', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1785, 74, 12, 'أكثر ما جاء التسبيح؛ مقرونًا بالحمد كقوله تعالى: ﴿وَسَبِّحۡ بِحَمۡدِ رَبِّكَ﴾ [طه: ١٣٠]، وقوله سبحانه: ﴿وَٱلۡمَلَٰٓئِكَةُ يُسَبِّحُونَ بِحَمۡدِ رَبِّهِمۡ﴾ [الشورى: ٥]، وكذا وردت أحاديث كثيرة عن رسولِ الله ﷺ قَرَنَ فيها التسبيح بالحمد، مثل قوله ﷺ في حديث أبي مالك الأشعري رضي الله عنه: «سبحان الله، والحمدُ لله تملآنِ -أو- تملأُ ما بين السماوات والأرض».', 0, 'اقتران التسبيح بالحمد. (ص319)', '', '', 'أكثر ما جاء التسبيح مقرونا بالحمد كقوله تعالى ﴿وسبحۡ بحمۡد ربك﴾ طه ١٣٠ وقوله سبحانه ﴿وٱلۡملئكة يسبحون بحمۡد ربهمۡ﴾ الشورى ٥ وكذا وردت أحاديث كثيرة عن رسول الله قرن فيها التسبيح بالحمد مثل قوله في حديث أبي مالك الأشعري رضي الله عنه «سبحان الله والحمد لله تملآن -أو- تملأ ما بين السماوات والأرض»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1786, 74, 13, 'وهذا كقوله عَزَّ وَجَلَّ:', 0, 'اقتران التسبيح بالحمد. (ص320)', '', '', 'وهذا كقوله عز وجل', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1787, 74, 14, 'QuranText[(37:180:182)]', 1, 'اقتران التسبيح بالحمد. [الصافات: ١٨٠- ١٨٢]. (ص320)', '', '', '37180182', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1788, 74, 15, 'سبحان الله وبحمده.', 1, 'اقتران التسبيح بالحمد. (ص320)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1789, 74, 16, 'سبحان الله وبحمده، سبحان الله العظيم.', 1, 'اقتران التسبيح بالحمد. (ص320)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1790, 74, 17, '٢- اقتران التسبيح بالتهليل:', 0, '(ص321)', '', '', '٢- اقتران التسبيح بالتهليل', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1791, 74, 18, '﴿ لَّآ إِلَٰهَ إِلَّآ أَنتَ سُبۡحَٰنَكَ إِنِّي كُنتُ مِنَ ٱلظَّٰلِمِينَ ﴾', 1, 'اقتران التسبيح بالتهليل. [الأنبياء: ٨٧]. (ص321)', '', '', '﴿ لا إله إلا أنت سبۡحنك إني كنت من ٱلظلمين ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1792, 74, 19, 'سبحانك وبحمدك، لا إله إلا أنت.', 1, 'اقتران التسبيح بالتهليل. (ص321)', '', '', 'سبحانك وبحمدك لا إله إلا أنت', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1793, 74, 20, '٣- اقتران التسبيح بالتكبير:', 0, '(ص321)', '', '', '٣- اقتران التسبيح بالتكبير', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1794, 74, 21, 'الله أكبرُ كبيرًا، والحمدُ لله كثيرًا، وسبحان الله بُكرةً وأصيلًا.', 1, 'اقتران التسبيح بالتكبير. (ص321)', '', '', 'الله أكبر كبيرا والحمد لله كثيرا وسبحان الله بكرة وأصيلا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1795, 74, 22, '٤- اقتران التسبيح بأسماء الله وصفاته:', 0, '(ص321)', '', '', '٤- اقتران التسبيح بأسماء الله وصفاته', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1796, 74, 23, 'سبحان ربي العظيم.', 1, 'اقتران التسبيح بأسماء الله وصفاته. (ص321)', '', '', 'سبحان ربي العظيم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1797, 74, 24, '﴿ سُبۡحَٰنَكَ ٱللَّهُمَّ ﴾', 1, 'اقتران التسبيح بأسماء الله وصفاته. [يونس: ١٠]. (ص322)', '', '', '﴿ سبۡحنك ٱللهم ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1798, 74, 25, 'سبحان ﴿ٱللَّهِ رَبِّ ٱلۡعَرۡشِ عَمَّا يَصِفُونَ﴾.', 1, 'اقتران التسبيح بأسماء الله وصفاته. [انظر: الآية (٢٢) سورة الأنبياء]. (ص322)', '', '', 'سبحان ﴿ٱلله رب ٱلۡعرۡش عما يصفون﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1799, 74, 26, 'سبحان ﴿ٱلَّذِي بِيَدِهِۦ مَلَكُوتُ كُلِّ شَيۡءٖ وَإِلَيۡهِ تُرۡجَعُونَ﴾.', 1, 'اقتران التسبيح بأسماء الله وصفاته. [انظر: الآية (٨٣) سورة يس]. (ص322)', '', '', 'سبحان ﴿ٱلذي بيدهۦ ملكوت كل شيۡء وإليۡه ترۡجعون﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1800, 74, 27, '﴿ سُبۡحَٰنَهُۥۖ هُوَ ٱللَّهُ ٱلۡوَٰحِدُ ٱلۡقَهَّارُ ﴾', 1, 'اقتران التسبيح بأسماء الله وصفاته. [الزمر: ٤]. (ص322)', '', '', '﴿ سبۡحنهۥۖ هو ٱلله ٱلۡوحد ٱلۡقهار ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1801, 74, 28, 'QuranText[(43:82:82)]', 1, 'اقتران التسبيح بأسماء الله وصفاته. [الزخرف: ٨٢]. (ص322)', '', '', '438282', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1802, 74, 29, 'سبحانَ الملكِ القُدُّوسِ.', 1, 'اقتران التسبيح بأسماء الله وصفاته. (ص322)', '', '', 'سبحان الملك القدوس', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1803, 74, 30, 'سبحان ذي الجبروتِ والملكوتِ والكبرياءِ والعَظَمَة.', 1, 'اقتران التسبيح بأسماء الله وصفاته. (ص322)', '', '', 'سبحان ذي الجبروت والملكوت والكبرياء والعظمة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1804, 74, 31, 'سبحان اللهِ لا شريكَ له، له الملكُ وله الحمدُ، وهو على كُلِّ شيءٍ قديرٌ، لا حولَ ولا قوَّةَ إلَّا بالله، سبحان الله وبحمده.', 1, 'اقتران التسبيح بأسماء الله وصفاته. (ص322)', '', '', 'سبحان الله لا شريك له له الملك وله الحمد وهو على كل شيء قدير لا حول ولا قوة إلا بالله سبحان الله وبحمده', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1805, 74, 32, '٥- اقتران التسبيح بالاستغفار:', 0, '(ص323)', '', '', '٥- اقتران التسبيح بالاستغفار', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1806, 74, 33, 'سبحان الله وبحمده، أستغفِرُ اللهَ، وأتوبُ إليه.', 1, 'اقتران التسبيح بالاستغفار. (ص323)', '', '', 'سبحان الله وبحمده أستغفر الله وأتوب إليه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1807, 74, 34, 'سبحانك اللهم ربَّنا وبحمدِكَ، اللهم اغفِرْ لِي.', 1, 'اقتران التسبيح بالاستغفار. (ص323)', '', '', 'سبحانك اللهم ربنا وبحمدك اللهم اغفر لي', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1808, 177, 1, 'النوع السابع: وِرْدُ التحميد', 0, '(ص324)', '', '', 'النوع السابع ورد التحميد', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1809, 177, 2, 'الحمدُ إخبارٌ عن محاسن الممدوح مع حُبِّه وإجلاله وتعظيمه.', 0, 'النوع السابع: وِرْدُ التحميد. (ص324)', '', '', 'الحمد إخبار عن محاسن الممدوح مع حبه وإجلاله وتعظيمه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1810, 177, 3, 'وقد افتتح الله كتابَه المجيدَ بالحمد: ﴿ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ﴾، وافتتح به سورَ: الأنعام، والكهف، وسبأ، وفاطر، وافتتح خَلْقَه بالحمد: ﴿ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ﴾ [الأنعام: ١]، واختتمه بالحمد: ﴿وَقُضِيَ بَيۡنَهُم بِٱلۡحَقِّۚ وَقِيلَ ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ﴾ [الزمر: ٧٥].', 0, 'النوع السابع: وِرْدُ التحميد. (ص324)', '', '', 'وقد افتتح الله كتابه المجيد بالحمد ﴿ٱلۡحمۡد لله رب ٱلۡعلمين﴾ وافتتح به سور الأنعام والكهف وسبأ وفاطر وافتتح خلقه بالحمد ﴿ٱلۡحمۡد لله ٱلذي خلق ٱلسموت وٱلۡأرۡض﴾ الأنعام ١ واختتمه بالحمد ﴿وقضي بيۡنهم بٱلۡحقۚ وقيل ٱلۡحمۡد لله رب ٱلۡعلمين﴾ الزمر ٧٥', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1811, 177, 4, 'وجعل آخرَ دعاءِ أهلِ الجنةِ الحمدَ: ﴿وَءَاخِرُ دَعۡوَىٰهُمۡ أَنِ ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ﴾ [يونس: ١٠]، ﴿لَهُ ٱلۡحَمۡدُ فِي ٱلۡأُولَىٰ وَٱلۡأٓخِرَةِۖ﴾ [القصص: ٧٠]، ﴿وَلَهُ ٱلۡحَمۡدُ فِي ٱلۡأٓخِرَةِۚ﴾ [سبأ: ١].', 0, 'النوع السابع: وِرْدُ التحميد. (ص324)', '', '', 'وجعل آخر دعاء أهل الجنة الحمد ﴿وءاخر دعۡوىهمۡ أن ٱلۡحمۡد لله رب ٱلۡعلمين﴾ يونس ١٠ ﴿له ٱلۡحمۡد في ٱلۡأولى وٱلۡأخرةۖ﴾ القصص ٧٠ ﴿وله ٱلۡحمۡد في ٱلۡأخرةۚ﴾ سبأ ١', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1812, 177, 5, 'وأمر بحمده فقال: ﴿وَقُلِ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي لَمۡ يَتَّخِذۡ وَلَدٗا وَلَمۡ يَكُن لَّهُۥ شَرِيكٞ فِي ٱلۡمُلۡكِ﴾ [الإسراء: ١١١].', 0, 'النوع السابع: وِرْدُ التحميد. (ص324)', '', '', 'وأمر بحمده فقال ﴿وقل ٱلۡحمۡد لله ٱلذي لمۡ يتخذۡ ولدا ولمۡ يكن لهۥ شريك في ٱلۡملۡك﴾ الإسراء ١١١', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1813, 177, 6, 'عن الأسود بن سريع، قال: كنت شاعرًا، فقلت: يا رسول الله! امتدحتُ ربي، فقال: «أما إنَّ رَبَّك يُحِبُّ المَحامِدَ»، وما استزادني على ذلك.', 0, 'النوع السابع: وِرْدُ التحميد. (ص325)', '', '', 'عن الأسود بن سريع قال كنت شاعرا فقلت يا رسول الله! امتدحت ربي فقال «أما إن ربك يحب المحامد» وما استزادني على ذلك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1814, 177, 7, 'والله تبارك وتعالى هو الحميد في ذاته وأسمائه وصفاته وأفعاله، وهو تبارك وتعالى المستحقُّ لكلِّ حمدٍ ومحبة وثناءٍ لما اتَّصف به من صفات الحمد التي هي الجمال والجلال، ولما أنعم به على خلقه من النِّعم الجزال، فهو المحمود على كلِّ حالٍ، وهو سبحانه حميدٌ مِن جميع الوجوه: «لأن جميع أسمائه تبارك وتعالى حمدٌ، وصفاته حمدٌ، وأفعاله حمدٌ، وأحكامه حمدٌ، وعدله حمد، وانتقامه حمد، وفضله في إحسانه إلى أوليائه حمد، والخلق والأمر إنما قام بحمده، ووُجِد بحمده، وظهر بحمده، وكان الغاية هي حمده، فحمدُه سببُ ذلك وغايته»، و«جميع ما يُوصَف به ويُذكَر به ويُخبَر عنه به فهو محامِدُ له وثناءٌ وتسبيح وتقديس، فسبحانه وبحمده لا يُحصِي أحدٌ مِن خَلْقِهِ ثناءً عليه بل هو كما أثنى على نفسه، وفوق ما يُثني به عليه خَلْقُه، فله الحمدُ أولًا وآخِرًا حمدًا كثيرًا طيبًا مباركًا فيه كما ينبغي لِكَرَمِ وَجْهِهِ، وعِزِّ جَلالِه، ورفيعِ مجدِه، وعلوِّ جَدِّه».', 0, 'النوع السابع: وِرْدُ التحميد. (ص325–326)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1815, 177, 8, 'وهو سبحانه كما أنه محمودٌ على أسمائه وصفاته فهو محمودٌ على فضله وعطائه ونعمائه لما له على عباده «من جزيل مواهبه، وسَعة عطاياه، وكريم أياديه، وجميل صنائعه، وحسن معاملته لعباده، وسَعةِ رحمته لهم، وبرِّه ولُطفه وحنانه، وإجابته لدعوات المضطرين، وكشف كربات المكروبين، وإغاثة الملهوفين، ورحمته للعالمين، وابتدائه بالنِّعَم قبلَ السؤال»، إلى غير ذلك من نعمه وعطائه، وأهم ذلك وأعظمه: «هدايتُه خاصَّتَه وعبادَه إلى سبيل دار السلام، ومدافعته عنهم أحسنَ الدفاع، وحمايتهم عن مراتع الآثام، وأنه حبَّب إليهم الإيمان وزيَّنه في قلوبهم، وكرَّه إليهم الكفرَ والفسوقَ والعِصيانَ، وجعلهم من الراشدين».', 0, 'النوع السابع: وِرْدُ التحميد. (ص326)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1816, 177, 9, 'وقد جاءت أحاديثُ شريفةٌ تخبر بفضيلة التحميد:', 0, '(ص327)', '', '', 'وقد جاءت أحاديث شريفة تخبر بفضيلة التحميد', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1817, 177, 10, 'منها قوله ﷺ: «... أفضلُ الدعاءِ الحمدُ لله».', 0, 'وقد جاءت أحاديث شريفة تخبر بفضيلة التحميد. (ص327)', '', '', 'منها قوله « أفضل الدعاء الحمد لله»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1818, 177, 11, 'ومنها قوله ﷺ: «الحمدُ للهِ تملأُ الميزانَ».', 0, 'وقد جاءت أحاديث شريفة تخبر بفضيلة التحميد. (ص327)', '', '', 'ومنها قوله «الحمد لله تملأ الميزان»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1819, 177, 12, 'ورُوِيَ عنه ﷺ أنه قال: «أول من يُدعى إلى الجنة الحمَّادون، الذين يَحْمَدُون اللهَ في السَّرَّاءِ والضراءِ».', 0, 'وقد جاءت أحاديث شريفة تخبر بفضيلة التحميد. (ص327)', '', '', 'وروي عنه أنه قال «أول من يدعى إلى الجنة الحمادون الذين يحمدون الله في السراء والضراء»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1820, 177, 13, 'وعن أبي موسى الأشعري رضي الله عنه أنَّ رسول الله ﷺ قال: «إذا مات ولدُ الرَّجُلِ يقولُ الله تعالى لملائكته: أقبضتُم وَلَدَ عبدي؟ فيقولون: نعم. فيقول: أَقَبَضْتُم ثَمَرَةَ فُؤادِه؟ فيقولون: نعم. فيقول: فماذا قال عبدي؟ فيقولون: حَمِدَك واسترجع. فيقول: ابنُوا لعبدي بيتًا في الجنَّةِ، وسَمُّوه بيتَ الحمدِ».', 0, 'وقد جاءت أحاديث شريفة تخبر بفضيلة التحميد. (ص327)', '', '', 'وعن أبي موسى الأشعري رضي الله عنه أن رسول الله قال «إذا مات ولد الرجل يقول الله تعالى لملائكته أقبضتم ولد عبدي فيقولون نعم فيقول أقبضتم ثمرة فؤاده فيقولون نعم فيقول فماذا قال عبدي فيقولون حمدك واسترجع فيقول ابنوا لعبدي بيتا في الجنة وسموه بيت الحمد»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1821, 177, 14, 'وكان رسول الله ﷺ إذا رأى ما يحبه قال: «الحمد لله الذي بنعمته تتمُّ الصالحاتُ»، وإذا رأى ما يكره قال: «الحمد للهِ على كلِّ حال».', 0, 'وقد جاءت أحاديث شريفة تخبر بفضيلة التحميد. (ص328)', '', '', 'وكان رسول الله إذا رأى ما يحبه قال «الحمد لله الذي بنعمته تتم الصالحات» وإذا رأى ما يكره قال «الحمد لله على كل حال»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1822, 177, 15, 'وعن أنس رضي الله عنه قال رسول الله ﷺ: «ما أنعم الله على عبدٍ بنعمةٍ فقال: (الحمد لله)؛ إلا كان ما أُعطِيَ أفضلَ مِمَّا أَخَذَ».', 0, 'وقد جاءت أحاديث شريفة تخبر بفضيلة التحميد. (ص328)', '', '', 'وعن أنس رضي الله عنه قال رسول الله «ما أنعم الله على عبد بنعمة فقال الحمد لله إلا كان ما أعطي أفضل مما أخذ»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1823, 177, 16, 'ومعناه: أن حَمْدَ الله على النعمة أفضلُ من النعمة نفسِها كما قال عمر بن عبد العزيز: «إن الله لم يُنْعِم على عبدٍ نعمةً فيحمد الله عليها؛ إلا كان حمدُه أفضلَ من نِعَمِهِ».', 0, 'وقد جاءت أحاديث شريفة تخبر بفضيلة التحميد. (ص328)', '', '', 'ومعناه أن حمد الله على النعمة أفضل من النعمة نفسها كما قال عمر بن عبد العزيز «إن الله لم ينعم على عبد نعمة فيحمد الله عليها إلا كان حمده أفضل من نعمه»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1824, 75, 1, 'من صِيَغِ الحمد', 0, '(ص329)', '', '', 'من صيغ الحمد', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1825, 75, 2, 'أولًا: في القرآن الكريم:', 0, '(ص329)', '', '', 'أولا في القرآن الكريم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1826, 75, 3, 'QuranText[(1:2:2)]', 1, 'أولًا: في القرآن الكريم. [الفاتحة: ١]. (ص329)', '', '', '122', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1827, 75, 4, '﴿ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي هَدَىٰنَا لِهَٰذَا وَمَا كُنَّا لِنَهۡتَدِيَ لَوۡلَآ أَنۡ هَدَىٰنَا ٱللَّهُۖ ﴾', 1, 'أولًا: في القرآن الكريم. [الأعراف: ٤٣]. (ص329)', '', '', '﴿ ٱلۡحمۡد لله ٱلذي هدىنا لهذا وما كنا لنهۡتدي لوۡلا أنۡ هدىنا ٱللهۖ ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1828, 75, 5, '﴿ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي لَمۡ يَتَّخِذۡ وَلَدٗا وَلَمۡ يَكُن لَّهُۥ شَرِيكٞ فِي ٱلۡمُلۡكِ وَلَمۡ يَكُن لَّهُۥ وَلِيّٞ مِّنَ ٱلذُّلِّۖ ﴾', 1, 'أولًا: في القرآن الكريم. [الإسراء: ١١١]. (ص329)', '', '', '﴿ ٱلۡحمۡد لله ٱلذي لمۡ يتخذۡ ولدا ولمۡ يكن لهۥ شريك في ٱلۡملۡك ولمۡ يكن لهۥ ولي من ٱلذلۖ ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1829, 75, 6, '﴿ ٱلۡحَمۡدُ لِلَّهِ وَسَلَٰمٌ عَلَىٰ عِبَادِهِ ٱلَّذِينَ ٱصۡطَفَىٰٓۗ ﴾', 1, 'أولًا: في القرآن الكريم. [النمل: ٥٩]. (ص329)', '', '', '﴿ ٱلۡحمۡد لله وسلم على عباده ٱلذين ٱصۡطفىۗ ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1830, 75, 7, 'ثانيًا: في السُّنَّة الشَّريفة:', 0, '(ص329)', '', '', 'ثانيا في السنة الشريفة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1831, 75, 8, 'الحمدُ لله حمدًا كثيرًا طيِّبًا مباركًا فيه مُبَارَكًا عليه، كما يُحِبُّ رَبُّنا ويَرْضَى.', 1, 'ثانيًا: في السنة الشريفة. (ص329)', '', '', 'الحمد لله حمدا كثيرا طيبا مباركا فيه مباركا عليه كما يحب ربنا ويرضى', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1832, 75, 9, 'الله أكبرُ كبيرًا، والحمد لله كثيرًا، وسبحانَ الله بُكرةً وأصيلًا.', 1, 'ثانيًا: في السنة الشريفة. (ص330)', '', '', 'الله أكبر كبيرا والحمد لله كثيرا وسبحان الله بكرة وأصيلا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1833, 75, 10, 'اللهم لك الحمدُ، أنتَ نورُ السماوات والأرض ومَنْ فيهنَّ، ولك الحمدُ، أنتَ قَيِّمُ السماواتِ والأرضِ ومَنْ فيهن، ولك الحمدُ، أنتَ مَلِكُ السماواتِ والأرضِ ومَن فيهن، ولك الحمدُ، أنت الحقُّ، ووعدُكَ حقٌّ، وقولُك حَقٌّ، ولقاؤك حقٌّ، والجنَّةُ حقٌّ، والنارُ حَقٌّ، والساعةُ حَقٌّ، والنبيون حَقٌّ، ومحمَّدٌ حَقٌّ.', 1, 'ثانيًا: في السنة الشريفة. (ص330)', '', '', 'اللهم لك الحمد أنت نور السماوات والأرض ومن فيهن ولك الحمد أنت قيم السماوات والأرض ومن فيهن ولك الحمد أنت ملك السماوات والأرض ومن فيهن ولك الحمد أنت الحق ووعدك حق وقولك حق ولقاؤك حق والجنة حق والنار حق والساعة حق والنبيون حق ومحمد حق', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1834, 75, 11, 'اللهم ربنا لك الحمد مِلءَ السماواتِ ومِلْءَ الأرضِ ومِلءَ ما بينهما، ومِلْءَ ما شئتَ من شيء بعد، أهلَ الثناءِ والمجد، أَحَقُّ ما قال العبدُ، وكُلُّنا لك عبدٌ، اللهم لا مانِعَ لما أعطيتَ، ولا مُعْطِيَ لما منعتَ، ولا ينفعُ ذا الجَدِّ منك الجَدُّ.', 1, 'ثانيًا: في السنة الشريفة. (ص330)', '', '', 'اللهم ربنا لك الحمد ملء السماوات وملء الأرض وملء ما بينهما وملء ما شئت من شيء بعد أهل الثناء والمجد أحق ما قال العبد وكلنا لك عبد اللهم لا مانع لما أعطيت ولا معطي لما منعت ولا ينفع ذا الجد منك الجد', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1835, 75, 12, 'لا إله إلا الله، الحمد لله رَبِّ العالمين.', 1, 'ثانيًا: في السنة الشريفة. (ص330)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1836, 172, 1, 'النوع الثامن: وِرْدُ التكبير', 0, '(ص331)', '', '', 'النوع الثامن ورد التكبير', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1837, 172, 2, 'أمر الله تعالى بتكبيره، فقال: ﴿وَرَبَّكَ فَكَبِّرۡ﴾ [المدثر: ٣]، وقال عَزَّ وَجَلَّ: ﴿وَكَبِّرۡهُ تَكۡبِيرَۢا﴾ [الإسراء: ١١١]، وقال سبحانه: ﴿وَلَهُ ٱلۡكِبۡرِيَآءُ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ﴾ [الجاثية: ٣٧].', 0, 'النوع الثامن: وِرْدُ التكبير. (ص331)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1838, 172, 3, 'قال الحافظُ ابنُ حجرٍ رحمه الله: «التكبيرُ ذكرٌ مأثورٌ عندَ كلِّ أمرٍ مَهُولٍ، وعندَ كُلِّ حادثِ سرورٍ، شكرًا لله تعالى، وتبرئةً له مِن كل ما نَسَبَ إليه أعداؤه».', 0, 'النوع الثامن: وِرْدُ التكبير. (ص331)', '', '', 'قال الحافظ ابن حجر رحمه الله «التكبير ذكر مأثور عند كل أمر مهول وعند كل حادث سرور شكرا لله تعالى وتبرئة له من كل ما نسب إليه أعداؤه»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1839, 172, 4, 'وقد شُرِعَ هذا الذكرُ العظيم إما قبل الشروع في عبادة أو بعدَها، أو في المواضع الكبار التي يجتمع فيها الناسُ، أو في حضور عدوٍّ من شياطين الجن أو الإنس، أو عند رؤية آية من آيات الله عَزَّ وَجَلَّ.', 0, 'النوع الثامن: وِرْدُ التكبير. (ص331–332)', '', '', 'وقد شرع هذا الذكر العظيم إما قبل الشروع في عبادة أو بعدها أو في المواضع الكبار التي يجتمع فيها الناس أو في حضور عدو من شياطين الجن أو الإنس أو عند رؤية آية من آيات الله عز وجل', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1840, 172, 5, 'وعن سر التكبير في هذه المواطن يقول شيخ الإسلام ابن تيمية رحمه الله بعد أن ساق بعض هذه المواضع: «... وهذا كله يبين أن التكبير مشروع في المواضع الكبار لكثرة الجَمْعِ، أو لعظمة الفعل، أو لقوة الحال، أو نحو ذلك من الأمور الكبيرة، ليبين أن الله أكبر، وتستولي كبرياؤه في القلوب على كبرياء تلك الأمور الكبار؛ فيكون الدين كله لله، ويكون العبادُ له مُكَبِّرين، فيحصل لهم مقصودان: مقصود العبادة بتكبير قلوبهم لله، ومقصود الاستعانة بانقياد المطالب لكبريائه، ولهذا شُرِع التكبير على الهداية والرزق والنصر؛ لأن هذه الثلاث أكبر ما يطلبه العبد، وهي جماع مصالحه، والهدى أعظم من الرزق والنصر، لأن الرزق والنصر قد لا يُنتَفَع بهما إلا في الدنيا، وأما الهدى فمنفعته في الآخرة قطعًا».', 0, 'النوع الثامن: وِرْدُ التكبير. (ص332)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1841, 172, 6, 'معنى التكبير:', 0, '(ص333)', '', '', 'معنى التكبير', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1842, 172, 7, 'معنى (الله أكبر) الله أكبرُ كبيرٍ، قال الفرزدق:', 0, 'معنى التكبير. (ص333)', '', '', 'معنى الله أكبر الله أكبر كبير قال الفرزدق', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1843, 172, 8, 'إن الَّذي سَمَكَ السَّمَاءَ بنى لنا بيتًا دَعَائِمُهُ أَعَزُّ وَأَطْوَلُ', 0, 'معنى التكبير. (ص333)', '', '', 'إن الذي سمك السماء بنى لنا بيتا دعائمه أعز وأطول', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1844, 172, 9, 'أي: أعزُّ عزيزٍ، وأطولُ طويلٍ.', 0, 'معنى التكبير. (ص333)', '', '', 'أي أعز عزيز وأطول طويل', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1845, 172, 10, 'قال شيخ الإسلام ابن تيمية: «التكبير يُراد به أن يكون (الله) عند العبد أكبر من كل شيء، كما قال ﷺ لعديِّ ابنِ حاتم: «يا عَدِيُّ ما يُفِرُّك؟ أيُفِرُّك أن يُقال: لا إله إلا الله؟ فهل تعلم مِنْ إلهٍ إلا الله؟ يا عدي ما يُفِرُّك؟ أيُفرك أن يقال: الله أكبر؟ فهل من شيء أكبر من الله»، وهذا يُبطل قولَ من جعل أكبر بمعنى كبير».اهـ.', 0, 'معنى التكبير. (ص333)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1846, 172, 11, 'وقد قيل: إن أبلغ لفظة للعرب في معنى التعظيم والإجلال هي: «الله أكبر».', 0, 'معنى التكبير. (ص334)', '', '', 'وقد قيل إن أبلغ لفظة للعرب في معنى التعظيم والإجلال هي «الله أكبر»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1847, 172, 12, 'قال خداش بن زهير:', 0, 'معنى التكبير. (ص334)', '', '', 'قال خداش بن زهير', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1848, 172, 13, 'رأيتُ اللهَ أكبرَ كلِّ شيءٍ محاولةً وأكثرَهم جنودا', 0, 'معنى التكبير. (ص334)', '', '', 'رأيت الله أكبر كل شيء محاولة وأكثرهم جنودا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1849, 172, 14, 'فكل شيء له قَدْرٌ من التعظيم في نفوس العباد؛ كان دون الذي هو مُتَّصِفٌ به عَزَّ وَجَلَّ، والله أكبر منه، «كما أنه سبحانه فوق ما يُثني عليه العباد، كما قال أعلم الناس به ﷺ: «لا أُحصِي ثَنَاءً عليك أنتَ كَمَا أثنيتَ على نَفسِك».', 0, 'معنى التكبير. (ص334–335)', '', '', 'فكل شيء له قدر من التعظيم في نفوس العباد كان دون الذي هو متصف به عز وجل والله أكبر منه «كما أنه سبحانه فوق ما يثني عليه العباد كما قال أعلم الناس به «لا أحصي ثناء عليك أنت كما أثنيت على نفسك»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1850, 172, 15, 'فكُلَّما قال العبدُ (الله أكبر) تحقَّق قلبه بأن يكون الله في قلبه أكبر من كل شيء؛ فلا يبقى لمخلوقٍ على القلب ربانية تُساوي ربانية الرب فضلًا عن أن تكون مِثْلَها.', 0, 'معنى التكبير. (ص335)', '', '', 'فكلما قال العبد الله أكبر تحقق قلبه بأن يكون الله في قلبه أكبر من كل شيء فلا يبقى لمخلوق على القلب ربانية تساوي ربانية الرب فضلا عن أن تكون مثلها', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1851, 172, 16, 'وهذا داخل في التوحيد لا إله إلا الله، فلا يكون في قلبه لمخلوق شيء من التَّألُّه؛ لا قليل ولا كثير، بل التَّألُّه كله لله».', 0, 'معنى التكبير. (ص335)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1852, 172, 17, 'وكبرياء الله عَزَّ وَجَلَّ وعظمته وجلاله وكماله وسائر صفاته يستحيل أن تحيط بها العقول، أو تدركها الأفهام، وإذا كانت العقول عاجزة عن إدراك كثير من مخلوقات الله تعالى العظيمة؛ فكيف يمكن أن تدرك عظمة الرب سبحانه وتعالى، قال الله عَزَّ وَجَلَّ: ﴿وَسِعَ كُرۡسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَۖ﴾ [البقرة: ٢٥٥].', 0, 'معنى التكبير. (ص335)', '', '', 'وكبرياء الله عز وجل وعظمته وجلاله وكماله وسائر صفاته يستحيل أن تحيط بها العقول أو تدركها الأفهام وإذا كانت العقول عاجزة عن إدراك كثير من مخلوقات الله تعالى العظيمة فكيف يمكن أن تدرك عظمة الرب سبحانه وتعالى قال الله عز وجل ﴿وسع كرۡسيه ٱلسموت وٱلۡأرۡضۖ﴾ البقرة ٢٥٥', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1853, 172, 18, 'وعن أبي ذر رضي الله عنه قال: سمعت رسول الله ﷺ يقول: «ما الكرسيُّ في العرشِ إلَّا كَحَلْقَةٍ مِنْ حَديدٍ أُلقِيَتْ بين ظَهْرَيْ فَلاةٍ من الأرض».', 0, 'معنى التكبير. (ص336)', '', '', 'وعن أبي ذر رضي الله عنه قال سمعت رسول الله يقول «ما الكرسي في العرش إلا كحلقة من حديد ألقيت بين ظهري فلاة من الأرض»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1854, 172, 19, 'وعن جابر بن عبد الله رضي الله عنهما أن رسول الله ﷺ قال: «أُذِنَ لي أن أُحدِّثَ عن مَلَكٍ من ملائكةِ اللهِ تعالى مِن حَمَلَةِ العرش؛ إنَّ ما بين شَحمةِ أُذُنِهِ إلى عاتقه مسيرة سَبْعِ مِئَةِ عام».', 0, 'معنى التكبير. (ص336)', '', '', 'وعن جابر بن عبد الله رضي الله عنهما أن رسول الله قال «أذن لي أن أحدث عن ملك من ملائكة الله تعالى من حملة العرش إن ما بين شحمة أذنه إلى عاتقه مسيرة سبع مئة عام»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1855, 172, 20, 'وعن عبد الله بن سلام رضي الله عنه قال رسول الله ﷺ: «لا تَفَكَّروا في الله، تَفَكَّروا فيما خَلَقَ اللهُ».', 0, 'معنى التكبير. (ص336)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1856, 172, 21, 'وعن سالم بن عبد الله بن عمر عن أبيه رضي الله عنه قال: قال رسول الله ﷺ: «تَفَكَّرُوا في آلاءِ الله، ولا تَفَكَّروا في الله».', 0, 'معنى التكبير. (ص337)', '', '', 'وعن سالم بن عبد الله بن عمر عن أبيه رضي الله عنه قال قال رسول الله «تفكروا في آلاء الله ولا تفكروا في الله»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1857, 172, 22, 'وعن أبي هريرةَ رضي الله عنه أنَّ رسولَ الله ﷺ قال: «قال الله تعالى: أعددتُ لعبادي الصالحين ما لا عينٌ رأَت، ولا أذن سَمِعَت، ولا خَطَرَ على قلبِ بشر». قال أبو هريرة رضي الله عنه: فاقرؤوا إن شئتم: ﴿فَلَا تَعۡلَمُ نَفۡسٞ مَّآ أُخۡفِيَ لَهُم مِّن قُرَّةِ أَعۡيُنٖ جَزَآءَۢ بِمَا كَانُواْ يَعۡمَلُونَ﴾ [السجدة: ١٧]».', 0, 'معنى التكبير. (ص337)', '', '', 'وعن أبي هريرة رضي الله عنه أن رسول الله قال «قال الله تعالى أعددت لعبادي الصالحين ما لا عين رأت ولا أذن سمعت ولا خطر على قلب بشر» قال أبو هريرة رضي الله عنه فاقرؤوا إن شئتم ﴿فلا تعۡلم نفۡس ما أخۡفي لهم من قرة أعۡين جزاءۢ بما كانوا يعۡملون﴾ السجدة ١٧ »', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1858, 172, 23, 'فإذا كان نعيمُ أهلِ الجنة -وهي مِن خَلْقِ الله- يعجزُ العقلُ والحواسُّ عن إداراكِهِ مهما حاولَ تخيُّلَه، فما بالُكَ بعظمةِ الخالقِ عَزَّ وَجَلَّ؟', 0, 'معنى التكبير. (ص337)', '', '', 'فإذا كان نعيم أهل الجنة -وهي من خلق الله- يعجز العقل والحواس عن إداراكه مهما حاول تخيله فما بالك بعظمة الخالق عز وجل', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1859, 76, 1, 'من صيغ التكبير:', 0, '(ص338)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1860, 76, 2, 'الله أكبر.', 1, 'من صيغ التكبير. (ص338)', '', '', 'الله أكبر', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1861, 76, 3, 'الله أكبر، الله أكبر، الله أكبر، ذو الملكوتِ والجبروتِ والكبرياءِ والعظمة.', 1, 'من صيغ التكبير. (ص338)', '', '', 'الله أكبر الله أكبر الله أكبر ذو الملكوت والجبروت والكبرياء والعظمة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1862, 76, 4, 'الله أكبر، الله أكبر، الله أكبر كبيرًا.', 1, 'من صيغ التكبير. (ص338)', '', '', 'الله أكبر الله أكبر الله أكبر كبيرا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1863, 76, 5, 'الله أكبر، الله أكبر، الله أكبر، ولله الحمد، الله أكبر وأجلُّ، الله أكبر على ما هدانا.', 1, 'من صيغ التكبير. (ص338)', '', '', 'الله أكبر الله أكبر الله أكبر ولله الحمد الله أكبر وأجل الله أكبر على ما هدانا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1864, 76, 6, 'الله أكبر، الله أكبر، الله أكبر، لا إله إلا الله، والله أكبر، الله أكبر، الله أكبر، ولله الحمد.', 1, 'من صيغ التكبير. (ص338)', '', '', 'الله أكبر الله أكبر الله أكبر لا إله إلا الله والله أكبر الله أكبر الله أكبر ولله الحمد', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1865, 76, 7, 'الله أكبرُ كبيرًا، الله أكبرُ كبيرًا، الله أكبر وأجل، الله أكبر، ولله الحمد.', 1, 'من صيغ التكبير. (ص338)', '', '', 'الله أكبر كبيرا الله أكبر كبيرا الله أكبر وأجل الله أكبر ولله الحمد', '', '');
